use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let cents = input.as_i64().unwrap();
    let n = input.as_i64().unwrap();
    let mut shares = Vec::new();

    for _ in 0..n {
        let share = cents / (n as i64);
        shares.push(share);
        cents -= share;
    }

    shares.sort_unstable();
    shares.into_iter().map(|share| serde_json::Value::from(share)).collect()
}
